// Robust alternatives generator (replace the existing code in Generate Alternatives)
const input = $json || {};

// Helper: try to parse common date string formats into a Date object
function tryParseDate(s) {
  if (!s) return null;
  let t = String(s).trim();

  // If format like 'YYYY-MM-DD HH:MM' -> convert first space to 'T'
  if (/^\d{4}-\d{2}-\d{2}\s+\d{1,2}[:]/.test(t)) {
    t = t.replace(' ', 'T');
  }

  // If no timezone indicator (Z or ±HH:MM), append Z (assume UTC)
  if (!/[zZ]$/.test(t) && !/[+\-]\d{2}:\d{2}$/.test(t)) {
    t = t + 'Z';
  }

  const d = new Date(t);
  if (!isNaN(d)) return d;

  // Last fallback: try original string
  const d2 = new Date(String(s));
  if (!isNaN(d2)) return d2;

  return null;
}

// Look for candidate start fields (order matters)
const candidates = [
  input.startISO,
  input.start && input.start.dateTime, // event objects from Google Calendar
  input.start && input.start.date,     // all-day events
  input.start,                         // top-level string
  input.start_raw,
  input.appointment && input.appointment.startISO,
  input.appointment && input.appointment.start,
  input.appointment && (input.appointment.date && input.appointment.time && (input.appointment.date + 'T' + input.appointment.time + ':00')),
];

// pick first non-empty candidate
let startRaw = null;
for (const c of candidates) {
  if (c) { startRaw = c; break; }
}

if (!startRaw) {
  throw new Error('No start candidate found. Candidates inspected: ' + JSON.stringify(candidates));
}

const startDate = tryParseDate(startRaw);
if (!startDate) {
  throw new Error('Invalid start time: ' + JSON.stringify(startRaw));
}

// Build alternative times (30m and 60m after)
const alt1 = new Date(startDate.getTime() + 30 * 60 * 1000);
const alt2 = new Date(startDate.getTime() + 60 * 60 * 1000);

return [{
  json: {
    alternatives: [alt1.toISOString(), alt2.toISOString()],
    parsedStartRaw: startRaw,
    parsedStartISO: startDate.toISOString()
  }
}];
